(()=>{'use strict';const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];const q=$('[data-hub-search]'),cards=$$('[data-tool-card]'),filters=$$('[data-tool-filter]'),count=$('[data-tool-count]'),empty=$('[data-tool-empty]'),recentBox=$('[data-recent-section]'),recentList=$('[data-recent-list]');if(!q||!cards.length)return;const key='cbl-recent-tools-v1';let category='all';const readRecent=()=>{try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return[]}};const saveRecent=item=>{const a=readRecent().filter(x=>x.slug!==item.slug);a.unshift(item);localStorage.setItem(key,JSON.stringify(a.slice(0,4)))};const renderRecent=()=>{const a=readRecent();if(!a.length){recentBox.hidden=true;return}recentBox.hidden=false;recentList.innerHTML=a.map(x=>'<a class="recent-chip" href="'+x.href+'"><b>'+x.mark+'</b>'+x.name+'</a>').join('')};const norm=s=>String(s||'').toLowerCase().normalize('NFKC');const run=()=>{const text=norm(q.value.trim());let n=0;cards.forEach(c=>{const cat=c.dataset.category||'',hay=norm(c.textContent+' '+(c.dataset.keywords||'')),okCat=category==='all'||cat===category,okText=!text||hay.includes(text),show=okCat&&okText;c.hidden=!show;if(show)n++});count.textContent=n+'件';empty.hidden=n>0};q.addEventListener('input',run);filters.forEach(b=>b.addEventListener('click',()=>{filters.forEach(x=>x.classList.remove('active'));b.classList.add('active');category=b.dataset.toolFilter||'all';run()}));cards.forEach(c=>c.addEventListener('click',()=>saveRecent({slug:c.dataset.slug,name:c.dataset.name,href:c.getAttribute('href'),mark:c.dataset.mark||'TOOL'})));document.addEventListener('keydown',e=>{if(e.key==='/'&&!/input|textarea|select/i.test(document.activeElement.tagName)){e.preventDefault();q.focus()}});renderRecent();run()})();